package work.solour.pulse;
import android.bluetooth.*;import android.bluetooth.le.*;import android.content.*;import android.os.*;import java.util.*;
@SuppressWarnings("deprecation") public class Ble {
 final SessionService s; BluetoothGatt g; BluetoothLeScanner scanner; public String status="未连接（不会自动模拟）"; public final List<BluetoothDevice> found=new ArrayList<>(); final ArrayDeque<BluetoothGattCharacteristic> subscriptions=new ArrayDeque<>(); long crank=-1,event=-1;long crankAt=0;
 Ble(SessionService s){this.s=s;}
 final ScanCallback scan=new ScanCallback(){public void onScanResult(int t,ScanResult r){BluetoothDevice d=r.getDevice();if(!found.contains(d))found.add(d);}public void onScanFailed(int e){status="扫描失败 "+e;}};
 public void scan(){try{BluetoothManager m=(BluetoothManager)s.getSystemService(Context.BLUETOOTH_SERVICE);BluetoothAdapter a=m.getAdapter();if(a==null||!a.isEnabled()){status="请先开启蓝牙";return;}scanner=a.getBluetoothLeScanner();found.clear();scanner.startScan(scan);status="扫描中（10秒）";s.h.postDelayed(()->{stopScan();if(g==null)status="扫描完成，请选择设备";},10000);}catch(Exception e){status="蓝牙权限或系统限制："+e.getClass().getSimpleName();}}
 void stopScan(){try{if(scanner!=null)scanner.stopScan(scan);}catch(Exception ignored){}}
 public void connect(int i){try{stopScan();if(g!=null)g.close();s.e.disconnect();crank=event=-1;status="连接中";g=found.get(i).connectGatt(s,false,cb,BluetoothDevice.TRANSPORT_LE);}catch(Exception e){status="连接失败："+e.getClass().getSimpleName();}}
 static UUID id(String shortId){return UUID.fromString("0000"+shortId+"-0000-1000-8000-00805f9b34fb");}
 void next(){try{BluetoothGattCharacteristic c=subscriptions.poll();if(c==null){status="已连接 · 标准服务订阅完成";return;}g.setCharacteristicNotification(c,true);BluetoothGattDescriptor d=c.getDescriptor(id("2902"));if(d!=null){d.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);if(!g.writeDescriptor(d))next();}else next();}catch(Exception e){status="订阅失败，请重新连接";}}
 final BluetoothGattCallback cb=new BluetoothGattCallback(){public void onConnectionStateChange(BluetoothGatt x,int code,int state){s.h.post(()->{if(x!=g)return;if(state==BluetoothProfile.STATE_CONNECTED){status="发现标准服务";try{x.discoverServices();}catch(Exception e){status="服务发现失败";}}else{status="已断连 · 数据将显示缺失";s.e.disconnect();}});}public void onServicesDiscovered(BluetoothGatt x,int code){s.h.post(()->{if(x!=g)return;subscriptions.clear();String[][] ids={{"180d","2a37"},{"1814","2a53"},{"1816","2a5b"}};for(String[] pair:ids){BluetoothGattService v=x.getService(id(pair[0]));if(v!=null){BluetoothGattCharacteristic c=v.getCharacteristic(id(pair[1]));if(c!=null)subscriptions.add(c);}}if(subscriptions.isEmpty())status="设备无支持的标准测量服务";else next();});}public void onDescriptorWrite(BluetoothGatt x,BluetoothGattDescriptor d,int st){s.h.post(()->{if(x==g){if(st!=0)status="部分服务订阅失败 "+st;next();}});}public void onCharacteristicChanged(BluetoothGatt x,BluetoothGattCharacteristic c){byte[] b=c.getValue();UUID u=c.getUuid();if(b!=null)s.h.post(()->{if(x==g)parse(u,b);});}};
 static int u16(byte[] b,int p){return (b[p]&255)|((b[p+1]&255)<<8);} static long u32(byte[] b,int p){return (long)u16(b,p)|((long)u16(b,p+2)<<16);}
 void parse(UUID u,byte[] b){try{long now=SystemClock.elapsedRealtime();if(u.equals(id("2a37")))s.e.heart(Engine.parseHr(b),now);else if(u.equals(id("2a53"))&&b.length>=4){s.e.velocity(u16(b,1)/256.0,now);s.e.cadence(b[3]&255,now);}else if(u.equals(id("2a5b"))){int p=1;if((b[0]&1)!=0)p+=6;if((b[0]&2)!=0&&b.length>=p+4){long c=u16(b,p),t=u16(b,p+2);if(crank>=0&&now-crankAt<60000){long dc=(c-crank)&65535,dt=(t-event)&65535;if(dt>0&&dc>0&&dc<100)s.e.cadence((int)Math.round(dc*60.0*1024/dt),now);}crank=c;event=t;crankAt=now;}}}catch(RuntimeException ignored){status="忽略不完整测量包";}}
 void close(){stopScan();try{if(g!=null){g.disconnect();g.close();g=null;}}catch(Exception ignored){}}
}
